import { Dimensions, Platform, StyleSheet } from 'react-native';

const { width, height } = Dimensions.get('window');

export const styles = StyleSheet.create({
    // --- 基础容器 ---
    container: {
        flex: 1,
        backgroundColor: '#F5F6F7',
    },

    // --- 顶部 Header 区域 ---
    headerContainer: {
        backgroundColor: '#fff',
        borderBottomWidth: StyleSheet.hairlineWidth,
        borderBottomColor: '#EEE',
        position: 'relative',
        // 确保下拉菜单不被列表遮挡
        ...Platform.select({
            ios: { zIndex: 10 },
            android: { elevation: 10 }
        })
    },

    // --- 胶囊搜索条外层 ---
    searchBarContainer: {
        flexDirection: 'row',
        alignItems: 'center',
        paddingHorizontal: 8, // 减少边距，为内部留空间
        paddingVertical: 8,
        backgroundColor: '#fff',
    },

    backButton: { 
        width: 32, 
        height: 32,
        justifyContent: 'center', 
        alignItems: 'center' 
    },
    backIcon: { fontSize: 20, color: '#333' },

    // 搜索框主体 - flex: 1 是关键，它会占据除了返回键之外的所有空间
    searchMainContent: {
        flex: 1,
        flexDirection: 'row',
        alignItems: 'center',
        backgroundColor: '#F2F4F7', 
        borderRadius: 20,          
        paddingHorizontal: 10,
        paddingVertical: 4,
        height: 40,
    },

    cityText: { 
        fontSize: 14, 
        fontWeight: 'bold', 
        color: '#333', 
        marginRight: 6,
        maxWidth: 50, // 限制超长城市名，防止挤压日期
    },

    // 日期列和晚数横向排列
    dateVerticalContainer: {
        flexDirection: 'row',
        alignItems: 'center',
    },

    dateInfoColumn: {
        flexDirection: 'column',
        justifyContent: 'center',
    },

    dateRow: {
        flexDirection: 'row',
        alignItems: 'center',
        height: 14, // 固定高度压缩行间距
    },

    dateLabel: {
        fontSize: 9,
        color: '#999',
        marginRight: 2,
    },

    dateValue: {
        fontSize: 10,
        color: '#0086F6',
        fontWeight: '600',
    },

    nightCountText: {
        fontSize: 10,
        color: '#666',
        marginHorizontal: 6,
        paddingLeft: 6,
        borderLeftWidth: StyleSheet.hairlineWidth,
        borderLeftColor: '#CCC',
    },

    verticalDivider: { 
        width: 1, 
        height: 16, 
        backgroundColor: '#DDD', 
        marginHorizontal: 8 
    },

    // 关键词区域 - flex: 1 自动占满剩余空间
    keywordContainer: { 
        flex: 1, 
        flexDirection: 'row', 
        alignItems: 'center' 
    },

    searchIcon: { fontSize: 12, marginRight: 4, color: '#999' },

    keywordPlaceholder: { 
        fontSize: 12, 
        color: '#333', 
        flex: 1, 
        padding: 0, // 必须为0，防止 Android 默认高度撑破布局
    },

    // --- 筛选栏 Tab ---
    filterRow: {
        flexDirection: 'row',
        justifyContent: 'space-around',
        paddingVertical: 12,
        backgroundColor: '#fff',
    },
    filterItem: {
        flexDirection: 'row',
        alignItems: 'center',
        justifyContent: 'center',
        flex: 1, 
    },
    filterText: { fontSize: 13, color: '#666' },
    activeFilterText: { color: '#0086F6', fontWeight: 'bold' },
    arrowIcon: { fontSize: 10, marginLeft: 4, color: '#999' },
    activeArrowIcon: { color: '#0086F6' },

    // --- 下拉菜单 ---
    dropdownContainer: {
        position: 'absolute',
        top: '100%', 
        left: 0,
        right: 0,
        height: height, 
    },
    mask: {
        ...StyleSheet.absoluteFillObject,
        backgroundColor: 'rgba(0,0,0,0.5)',
    },
    dropdownContent: {
        backgroundColor: '#fff',
        borderBottomLeftRadius: 12,
        borderBottomRightRadius: 12,
        maxHeight: height * 0.6,
        overflow: 'hidden',
    },
    dropdownList: { paddingVertical: 5 },
    dropdownItem: {
        flexDirection: 'row',
        justifyContent: 'space-between',
        paddingVertical: 14,
        paddingHorizontal: 20,
        borderBottomWidth: StyleSheet.hairlineWidth,
        borderBottomColor: '#f0f0f0',
    },
    dropdownItemText: { fontSize: 14, color: '#333' },
    activeDropdownItemText: { color: '#0086F6', fontWeight: 'bold' },

    // --- 综合筛选面板 ---
    panelContainer: { padding: 15 },
    sectionTitle: { fontSize: 14, fontWeight: 'bold', color: '#333', marginVertical: 10 },
    tagContainer: { flexDirection: 'row', flexWrap: 'wrap' },
    tagItem: {
        width: '31%',
        backgroundColor: '#F5F5F5',
        paddingVertical: 8,
        alignItems: 'center',
        borderRadius: 4,
        marginRight: '3.5%',
        marginBottom: 10,
        borderWidth: 1,
        borderColor: 'transparent',
    },
    tagItemNoMargin: { marginRight: 0 },
    activeTagItem: { backgroundColor: '#EAF6FF', borderColor: '#0086F6' },
    tagText: { fontSize: 12, color: '#666' },
    activeTagText: { color: '#0086F6', fontWeight: 'bold' },

    buttonGroup: {
        flexDirection: 'row',
        padding: 10,
        borderTopWidth: 1,
        borderTopColor: '#EEE',
    },
    resetBtn: {
        flex: 1,
        paddingVertical: 10,
        alignItems: 'center',
        backgroundColor: '#fff',
        borderWidth: 1,
        borderColor: '#DDD',
        marginRight: 10,
        borderRadius: 4,
    },
    confirmBtn: {
        flex: 2,
        paddingVertical: 10,
        alignItems: 'center',
        backgroundColor: '#0086F6',
        borderRadius: 4,
    },
    confirmBtnText: { color: '#fff', fontWeight: 'bold' },

    // --- 酒店卡片样式 ---
    hotelItem: {
        flexDirection: 'row',
        backgroundColor: '#fff',
        marginHorizontal: 12,
        marginTop: 12,
        borderRadius: 12,
        padding: 12,
        elevation: 2,
        shadowColor: '#000',
        shadowOffset: { width: 0, height: 2 },
        shadowOpacity: 0.05,
    },
    hotelImage: { width: 100, height: 135, borderRadius: 8 },
    infoArea: { flex: 1, marginLeft: 12, justifyContent: 'space-between' },
    hotelName: { fontSize: 16, fontWeight: 'bold', color: '#333' },
    starRow: { flexDirection: 'row', alignItems: 'center', marginTop: 4 },
    scoreText: { fontSize: 14, color: '#0086F6', fontWeight: 'bold', marginRight: 8 },
    commentText: { fontSize: 12, color: '#999' },
    addressText: { fontSize: 12, color: '#666', marginTop: 4 },
    tagRow: { flexDirection: 'row', flexWrap: 'wrap', marginTop: 4 },
    hotelTag: { backgroundColor: '#E8F3FF', paddingHorizontal: 6, paddingVertical: 2, borderRadius: 4, marginRight: 6, marginBottom: 4 },
    hotelTagText: { fontSize: 10, color: '#007AFF' },
    priceContainer: { flexDirection: 'row', alignItems: 'baseline', justifyContent: 'flex-end' },
    priceSymbol: { fontSize: 12, color: '#FF5A5F', fontWeight: 'bold' },
    priceText: { fontSize: 20, color: '#FF5A5F', fontWeight: 'bold' },
    priceUnit: { fontSize: 11, color: '#999', marginLeft: 2 },
    footerLoading: { paddingVertical: 20, alignItems: 'center' }
});
